const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{let open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');menu.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');menu.textContent='☰'}));
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn))});document.querySelectorAll('.project').forEach(p=>p.hidden=btn.dataset.filter!=='all'&&p.dataset.type!==btn.dataset.filter)}));
const defaultProjects={forma:{title:'Forma Studio',image:'forma.webp',description:'Conceito de site para um estúdio de arquitetura. Fotografias amplas, apresentação de projetos e um caminho direto para iniciar uma conversa. A identidade valoriza o cuidado e a personalidade de cada espaço.',tags:['Site institucional','Portfólio de projetos','Contato']},pulse:{title:'Pulse Athletics',image:'pulse.webp',description:'Conceito visual de uma loja esportiva. Produtos em destaque, navegação clara e uma identidade que comunica energia. Uma referência de como podemos planejar uma experiência de compra para sua marca.',tags:['E-commerce','Catálogo de produtos','Design responsivo']},salvia:{title:'Sálvia Restaurante',image:'salvia.webp',description:'Conceito de landing page para um restaurante. Gastronomia em destaque, atmosfera acolhedora e espaço para apresentar o cardápio, a localização e os canais de reserva.',tags:['Landing page','Apresentação do cardápio','Localização e reservas']}};
const projects=window.awContent?Object.fromEntries(window.awContent.portfolio.projects.map(p=>[p.id,p])):defaultProjects;
const projectDialog=document.querySelector('#project-dialog');document.querySelectorAll('[data-project]').forEach(btn=>btn.addEventListener('click',()=>{let p=projects[btn.dataset.project];document.querySelector('#dialog-image').src=window.awContent?p.image:'assets/'+p.image;document.querySelector('#dialog-image').alt='Conceito visual '+p.title;document.querySelector('#dialog-title').textContent=p.title;document.querySelector('#dialog-description').textContent=p.description;document.querySelector('#dialog-tags').replaceChildren(...p.tags.map(t=>{let s=document.createElement('span');s.textContent=t;return s}));document.querySelector('#project-dialog .eyebrow').textContent=p.concept===false?'PROJETO DO PORTFÓLIO':'PROJETO CONCEITUAL · MARCA FICTÍCIA';let live=document.querySelector('#dialog-live');if(!live){live=document.createElement('a');live.id='dialog-live';live.className='text-link';live.target='_blank';live.rel='noopener noreferrer';live.textContent='Abrir projeto ↗';document.querySelector('#dialog-tags').after(live)}live.hidden=!p.url;if(p.url)live.href=p.url;projectDialog.showModal()}));document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});document.querySelector('#dialog-contact').addEventListener('click',()=>projectDialog.close());
const form=document.querySelector('#brief-form'),emailDialog=document.querySelector('#email-dialog'),draft=document.querySelector('#email-draft');form.addEventListener('submit',e=>{e.preventDefault();if(!validateStep())return;if(briefStep<2){showBriefStep(briefStep+1);return}let d=new FormData(form);draft.value=`Olá, equipe awdevelop!\n\nMeu nome é ${d.get('name')}.\nMeu e-mail: ${d.get('email')}\nTenho interesse em: ${d.get('service')}.\nEmpresa/projeto: ${d.get('company')||'Não informado'}\nTelefone: ${d.get('phone')||'Não informado'}\nSituação atual: ${d.get('stage')}\nQuando quero começar: ${d.get('timeline')}\n\nMinha ideia:\n${d.get('idea')}\n\nGostaria de conversar sobre o projeto e receber uma proposta.`;document.querySelector('#copy-status').textContent='';emailDialog.showModal()});document.querySelector('#copy-draft').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(draft.value);document.querySelector('#copy-status').textContent='Mensagem copiada. Cole no canal de contato que preferir.'}catch{draft.focus();draft.select();document.querySelector('#copy-status').textContent='Selecione e copie a mensagem acima.'}});document.querySelector('#year').textContent=new Date().getFullYear();
// Portfolio banners: manual navigation, optional timed rotation, and reduced motion.
const carousel=document.querySelector('.portfolio-carousel'),slides=[...document.querySelectorAll('.portfolio-banner')],slideButtons=[...document.querySelectorAll('[data-slide]')],pauseButton=document.querySelector('#carousel-pause'),motion=window.matchMedia('(prefers-reduced-motion: reduce)');let currentSlide=0,rotationPaused=motion.matches,carouselTimer=null;function renderSlide(index,announce=false){currentSlide=(index+slides.length)%slides.length;slides.forEach((s,i)=>s.hidden=i!==currentSlide);slideButtons.forEach((b,i)=>{b.classList.toggle('selected',i===currentSlide);b.setAttribute('aria-pressed',String(i===currentSlide))});document.querySelector('.carousel-counter').textContent=String(currentSlide+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');if(announce)document.querySelector('#carousel-status').textContent=slides[currentSlide].getAttribute('aria-label')}function stopRotation(){clearInterval(carouselTimer);carouselTimer=null}function syncRotation(){stopRotation();pauseButton.textContent=rotationPaused?'Reproduzir':'Pausar';pauseButton.setAttribute('aria-pressed',String(rotationPaused));pauseButton.setAttribute('aria-label',rotationPaused?'Iniciar rotação automática':'Pausar rotação automática');if(!carousel.closest('[hidden]')&&!rotationPaused&&!document.hidden&&!carousel.matches(':hover')&&!carousel.contains(document.activeElement)&&!document.querySelector('dialog[open]'))carouselTimer=setInterval(()=>renderSlide(currentSlide+1),(window.awContent?.settings.rotationSeconds||6.5)*1000)}function selectManually(i){rotationPaused=true;renderSlide(i,true);syncRotation()}document.querySelector('#carousel-next').addEventListener('click',()=>selectManually(currentSlide+1));document.querySelector('#carousel-prev').addEventListener('click',()=>selectManually(currentSlide-1));slideButtons.forEach(b=>b.addEventListener('click',()=>selectManually(Number(b.dataset.slide))));pauseButton.addEventListener('click',()=>{rotationPaused=!rotationPaused;syncRotation()});carousel.addEventListener('mouseenter',stopRotation);carousel.addEventListener('mouseleave',syncRotation);carousel.addEventListener('focusin',stopRotation);carousel.addEventListener('focusout',()=>setTimeout(syncRotation,0));carousel.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.key==='ArrowRight'){e.preventDefault();selectManually(currentSlide+1)}else if(e.key==='ArrowLeft'){e.preventDefault();selectManually(currentSlide-1)}});document.addEventListener('visibilitychange',syncRotation);motion.addEventListener('change',e=>{if(e.matches)rotationPaused=true;syncRotation()});document.querySelectorAll('dialog').forEach(d=>{new MutationObserver(syncRotation).observe(d,{attributes:true,attributeFilter:['open']})});let touchStart=null;carousel.querySelector('.banner-art').parentNode.parentNode.addEventListener('touchstart',e=>{touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});carousel.querySelector('.banner-stage').addEventListener('touchend',e=>{if(!touchStart)return;let dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)selectManually(currentSlide+(dx<0?1:-1));touchStart=null},{passive:true});renderSlide(0);syncRotation();

// Guided brief: validate only the visible stage; preserve entered data when returning.
form.noValidate=true;const formSteps=[...document.querySelectorAll('.form-step')],nextStep=document.querySelector('#step-next'),backStep=document.querySelector('#step-back'),submitStep=document.querySelector('#step-submit');let briefStep=0;function validateStep(){for(const field of formSteps[briefStep].querySelectorAll('input,select,textarea')){if(!field.checkValidity()){field.reportValidity();return false}}return true}function showBriefStep(n){briefStep=n;formSteps.forEach((step,i)=>step.hidden=i!==n);document.querySelector('#step-label').textContent='Etapa '+(n+1)+' de 3';document.querySelector('#step-title').textContent=['Sua necessidade','Ponto de partida','Seu contato'][n];document.querySelector('#step-progress').style.width=((n+1)/3*100)+'%';backStep.hidden=n===0;nextStep.hidden=n===2;submitStep.hidden=n!==2;document.querySelector('#form-status').textContent='';const legend=formSteps[n].querySelector('legend');legend.tabIndex=-1;legend.focus({preventScroll:true})}nextStep.addEventListener('click',()=>{if(validateStep())showBriefStep(briefStep+1)});backStep.addEventListener('click',()=>showBriefStep(briefStep-1));form.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input')&&briefStep<2){e.preventDefault();if(validateStep())showBriefStep(briefStep+1)}});

let quoteRequestId=crypto.randomUUID();
const sendQuote=document.querySelector('#email-send');
sendQuote.addEventListener('click',async()=>{
 if(sendQuote.disabled)return;const d=new FormData(form);sendQuote.disabled=true;document.querySelector('#copy-status').textContent='Enviando solicitação…';
 const payload=Object.fromEntries(d);payload.consent=d.get('consent')==='on';payload.requestId=quoteRequestId;
 try{const response=await fetch('/api/quotes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível enviar agora.');
  document.querySelector('#copy-status').textContent='Solicitação recebida! Nossa equipe entrará em contato pelos dados informados.';sendQuote.textContent='Pedido recebido';form.reset();showBriefStep(0);quoteRequestId=crypto.randomUUID();
 }catch(error){document.querySelector('#copy-status').textContent=error.message;sendQuote.disabled=false;}
});
form.addEventListener('input',()=>{sendQuote.disabled=false;sendQuote.textContent='Enviar solicitação';document.querySelector('#copy-status').textContent='';});
